# Clean: convert string numeric columns
df["ECCENTRICITY"] = pd.to_numeric(df["ECCENTRICITY"], errors="coerce")

# Parse launch year from OBJECT_ID (first 4 chars)
df["LAUNCH_YEAR"] = df["OBJECT_ID"].str[:4].astype(str)
df["LAUNCH_YEAR_NUM"] = pd.to_numeric(
    df["LAUNCH_YEAR"].str.extract(r"(\d{4})")[0], errors="coerce"
)

# ── Orbit Classification ─────────────────────────────────────────────
def classify_orbit(row):
    mm = row["MEAN_MOTION"]
    ecc = row["ECCENTRICITY"]
    if pd.isna(mm):
        return "Unknown"
    if ecc is not None and not pd.isna(ecc) and ecc > 0.25:
        return "HEO"
    if mm > 14:
        return "LEO"
    if 0.9 <= mm <= 1.1:   # ~1 rev/day = GEO
        return "GEO"
    return "MEO"

df["ORBIT_REGIME"] = df.apply(classify_orbit, axis=1)

# ── Constellation Extraction ─────────────────────────────────────────
def extract_constellation(name):
    """Parse OBJECT_NAME prefix to identify constellation/operator."""
    name = str(name).strip().upper()
    # Known constellations/operators — order matters (longer prefixes first)
    patterns = [
        ("STARLINK", "Starlink"),
        ("ONEWEB", "OneWeb"),
        ("SPACEX", "SpaceX (non-Starlink)"),
        ("IRIDIUM", "Iridium"),
        ("GPS", "GPS"),
        ("GALILEO", "Galileo"),
        ("BEIDOU", "BeiDou"),
        ("GLONASS", "GLONASS"),
        ("YAOGAN", "Yaogan"),
        ("FLOCK", "Flock (Planet Labs)"),
        ("LEMUR", "Lemur (Spire)"),
        (" SENTINEL", "Sentinel (Copernicus)"),
        ("ORBCOMM", "Orbcomm"),
        ("GLOBALSTAR", "Globalstar"),
        ("RAPIDEYE", "RapidEye"),
        ("SWARM", "Swarm"),
        ("DOVE", "Dove (Planet Labs)"),
        ("TELESAT", "Telesat"),
        ("KINEIS", "Kineis"),
        ("FENGYUN", "Fengyun"),
        ("GAOFEN", "Gaofen"),
        ("ISS", "ISS"),
        ("INTELSAT", "Intelsat"),
        ("SES", "SES"),
        ("EUTELSAT", "Eutelsat"),
        ("INMARSAT", "Inmarsat"),
    ]
    for prefix, label in patterns:
        if name.startswith(prefix) or (" " + prefix) in name:
            return label
    return "Other"

df["CONSTELLATION"] = df["OBJECT_NAME"].apply(extract_constellation)

# ── Compute KPIs ─────────────────────────────────────────────────────
total_sats       = len(df)
leo_count        = (df["ORBIT_REGIME"] == "LEO").sum()
leo_pct          = leo_count / total_sats * 100
starlink_count   = (df["CONSTELLATION"] == "Starlink").sum()
