      <tr><td>Near-circular (ecc &lt; 0.01)</td><td>{(ecc < 0.01).sum():,} ({(ecc < 0.01).sum()/total_sats*100:.1f}%)</td></tr>
      <tr><td>Moderate (0.01 ≤ ecc &lt; 0.25)</td><td>{((ecc >= 0.01) & (ecc < 0.25)).sum():,}</td></tr>
