#!/usr/bin/env python3
"""Build the Active Satellites in Earth Orbit 2026 report as self-contained HTML."""

import base64
import io
import json
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import numpy as np
from pathlib import Path

# ── Styling ──────────────────────────────────────────────────────────
PRIMARY   = "#1b2a4a"   # dark navy
ACCENT    = "#2563eb"   # bright blue
ORBIT_COLORS = {
    "LEO": "#2563eb",
    "MEO": "#f59e0b",
    "GEO": "#10b981",
    "HEO": "#ef4444",
}
LEO_GRADIENT = ["#93c5fd", "#60a5fa", "#3b82f6", "#2563eb", "#1d4ed8", "#1e3a5f"]

BASE = Path("/app")
OUTPUT_DIR = BASE / "output"
OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

# ── Load & Clean Data ────────────────────────────────────────────────
print("Loading data...")
df = pd.read_csv(BASE / "benchmark" / "data.csv")

# Clean: convert string numeric columns
df["ECCENTRICITY"] = pd.to_numeric(df["ECCENTRICITY"], errors="coerce")

# Parse launch year from OBJECT_ID (first 4 chars)
df["LAUNCH_YEAR"] = df["OBJECT_ID"].str[:4].astype(str)
df["LAUNCH_YEAR_NUM"] = pd.to_numeric(
    df["LAUNCH_YEAR"].str.extract(r"(\d{4})")[0], errors="coerce"
)

# ── Orbit Classification ─────────────────────────────────────────────
def classify_orbit(row):
    mm = row["MEAN_MOTION"]
    ecc = row["ECCENTRICITY"]
    if pd.isna(mm):
        return "Unknown"
    if ecc is not None and not pd.isna(ecc) and ecc > 0.25:
        return "HEO"
    if mm > 14:
        return "LEO"
    if 0.9 <= mm <= 1.1:   # ~1 rev/day = GEO
        return "GEO"
    return "MEO"

df["ORBIT_REGIME"] = df.apply(classify_orbit, axis=1)

# ── Constellation Extraction ─────────────────────────────────────────
def extract_constellation(name):
    """Parse OBJECT_NAME prefix to identify constellation/operator."""
    name = str(name).strip().upper()
    # Known constellations/operators — order matters (longer prefixes first)
    patterns = [
        ("STARLINK", "Starlink"),
        ("ONEWEB", "OneWeb"),
        ("SPACEX", "SpaceX (non-Starlink)"),
        ("IRIDIUM", "Iridium"),
        ("GPS", "GPS"),
        ("GALILEO", "Galileo"),
        ("BEIDOU", "BeiDou"),
        ("GLONASS", "GLONASS"),
        ("YAOGAN", "Yaogan"),
        ("FLOCK", "Flock (Planet Labs)"),
        ("LEMUR", "Lemur (Spire)"),
        (" SENTINEL", "Sentinel (Copernicus)"),
        ("ORBCOMM", "Orbcomm"),
        ("GLOBALSTAR", "Globalstar"),
        ("RAPIDEYE", "RapidEye"),
        ("SWARM", "Swarm"),
        ("DOVE", "Dove (Planet Labs)"),
        ("TELESAT", "Telesat"),
        ("KINEIS", "Kineis"),
        ("FENGYUN", "Fengyun"),
        ("GAOFEN", "Gaofen"),
        ("ISS", "ISS"),
        ("INTELSAT", "Intelsat"),
        ("SES", "SES"),
        ("EUTELSAT", "Eutelsat"),
        ("INMARSAT", "Inmarsat"),
    ]
    for prefix, label in patterns:
        if name.startswith(prefix) or (" " + prefix) in name:
            return label
    return "Other"

df["CONSTELLATION"] = df["OBJECT_NAME"].apply(extract_constellation)

# ── Compute KPIs ─────────────────────────────────────────────────────
total_sats       = len(df)
leo_count        = (df["ORBIT_REGIME"] == "LEO").sum()
leo_pct          = leo_count / total_sats * 100
starlink_count   = (df["CONSTELLATION"] == "Starlink").sum()
median_incl      = df["INCLINATION"].median()
post_2020_mask   = df["LAUNCH_YEAR_NUM"] >= 2020
post_2020_count  = post_2020_mask.sum()
post_2020_pct    = post_2020_count / total_sats * 100

# Epoch range
df["EPOCH_DATE"] = pd.to_datetime(df["EPOCH"].str[:10], errors="coerce")
epoch_min = df["EPOCH_DATE"].min().strftime("%Y-%m-%d")
epoch_max = df["EPOCH_DATE"].max().strftime("%Y-%m-%d")

print(f"Total: {total_sats} | LEO: {leo_count} ({leo_pct:.1f}%) | "
      f"Starlink: {starlink_count} | Median Inc: {median_incl:.1f}° | "
      f"Post-2020: {post_2020_count} ({post_2020_pct:.1f}%)")

# ── Chart Helper ─────────────────────────────────────────────────────
def fig_to_b64(fig=None):
    """Convert matplotlib figure to base64 PNG string."""
    if fig is None:
        fig = plt.gcf()
    buf = io.BytesIO()
    fig.savefig(buf, format="png", dpi=150, bbox_inches="tight", facecolor="white")
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode()
    plt.close(fig)
    return f"data:image/png;base64,{b64}"

# ── Chart 1: Orbit Regime Pie ────────────────────────────────────────
print("Generating chart: orbit regime pie...")
regime_counts = df["ORBIT_REGIME"].value_counts()
fig, ax = plt.subplots(figsize=(7, 5))
wedges, texts, autotexts = ax.pie(
    regime_counts.values,
    labels=regime_counts.index,
    autopct=lambda p: f"{p:.1f}%\n({int(p/100*total_sats):,})",
    colors=[ORBIT_COLORS.get(r, "#94a3b8") for r in regime_counts.index],
    startangle=90,
    pctdistance=0.6,
    explode=(0.02, 0.02, 0.02, 0.02),
)
for t in autotexts:
    t.set_fontsize(8)
for t in texts:
    t.set_fontsize(10)
ax.set_title("Satellite Distribution by Orbital Regime", fontsize=13, fontweight="bold", color=PRIMARY)
orbit_pie_b64 = fig_to_b64(fig)

# ── Chart 2: Launch Trend (cumulative & annual) ──────────────────────
print("Generating chart: launch trends...")
launch_years = df["LAUNCH_YEAR_NUM"].dropna()
launch_years = launch_years[(launch_years >= 1960) & (launch_years <= 2026)]
annual = launch_years.value_counts().sort_index()
# Build cumulative
cumulative = annual.cumsum()

fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(10, 8), sharex=True,
                                gridspec_kw={'height_ratios': [1, 1.2]})

# Subplot 1: Cumulative
ax1.fill_between(cumulative.index, cumulative.values, alpha=0.3, color=ACCENT)
ax1.plot(cumulative.index, cumulative.values, color=ACCENT, linewidth=2)
ax1.set_ylabel("Active Satellites", fontsize=11, color=PRIMARY)
ax1.set_title("Cumulative Growth of the Active Satellite Fleet", fontsize=13,
              fontweight="bold", color=PRIMARY)
ax1.grid(axis="y", alpha=0.3)
ax1.axvline(x=2020, color="#ef4444", linestyle="--", alpha=0.5, linewidth=1)
ax1.annotate("2020\ninflection", xy=(2020, cumulative.get(2020, 0)),
             xytext=(2014, cumulative.max() * 0.85),
             arrowprops=dict(arrowstyle="->", color="#ef4444"), color="#ef4444", fontsize=9)

# Subplot 2: Annual (bar) — focus on later years
recent_annual = annual[annual.index >= 2000]
bars = ax2.bar(recent_annual.index, recent_annual.values,
               color=[ACCENT if y >= 2020 else "#93c5fd" for y in recent_annual.index],
               edgecolor="white", linewidth=0.3)
ax2.set_ylabel("Satellites Launched", fontsize=11, color=PRIMARY)
ax2.set_xlabel("Launch Year", fontsize=11, color=PRIMARY)
ax2.set_title("Annual Launch Count (Currently Active Satellites, 2000–2026)",
              fontsize=13, fontweight="bold", color=PRIMARY)
ax2.grid(axis="y", alpha=0.3)
ax2.axvline(x=2020, color="#ef4444", linestyle="--", alpha=0.5, linewidth=1)

plt.tight_layout()
launch_trend_b64 = fig_to_b64(fig)

# ── Chart 3: Top 15 Constellations ───────────────────────────────────
print("Generating chart: constellation breakdown...")
const_counts = df["CONSTELLATION"].value_counts()
top15 = const_counts.head(15)

fig, ax = plt.subplots(figsize=(10, 6))
colors_bars = [ACCENT if c == "Starlink" else "#94a3b8" for c in top15.index]
bars = ax.barh(range(len(top15)), top15.values[::-1], color=colors_bars[::-1])
ax.set_yticks(range(len(top15)))
ax.set_yticklabels(top15.index[::-1], fontsize=9)
ax.set_xlabel("Number of Active Satellites", fontsize=11, color=PRIMARY)
ax.set_title("Top 15 Satellite Constellations / Operators", fontsize=13,
             fontweight="bold", color=PRIMARY)
ax.grid(axis="x", alpha=0.3)

# Add count labels
for i, (bar, val) in enumerate(zip(bars, top15.values[::-1])):
    ax.text(bar.get_width() + 100, bar.get_y() + bar.get_height()/2,
            f"{val:,}", va="center", fontsize=8, color=PRIMARY)

const_bar_b64 = fig_to_b64(fig)

# ── Chart 4: Starlink vs. Rest ───────────────────────────────────────
print("Generating chart: Starlink dominance...")
starlink_pct = starlink_count / total_sats * 100
rest_count = total_sats - starlink_count

fig, ax = plt.subplots(figsize=(7, 5))
ax.pie(
    [starlink_count, rest_count],
    labels=["Starlink", "All Other Satellites"],
    colors=[ACCENT, "#e2e8f0"],
    autopct=lambda p: f"{p:.1f}%\n({int(p/100*total_sats):,})",
    startangle=90,
    explode=(0.05, 0),
    pctdistance=0.55,
    textprops={"fontsize": 11},
)
ax.set_title("Starlink's Share of the Active Satellite Population",
             fontsize=13, fontweight="bold", color=PRIMARY)
starlink_pie_b64 = fig_to_b64(fig)

# ── Chart 5: Inclination Distribution ────────────────────────────────
print("Generating chart: inclination distribution...")
incl = df["INCLINATION"].dropna()
fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 5))

# Histogram
ax1.hist(incl, bins=80, color=ACCENT, alpha=0.8, edgecolor="white", linewidth=0.3)
ax1.axvline(x=incl.median(), color="#ef4444", linestyle="--", linewidth=1.5,
            label=f"Median: {incl.median():.1f}°")
ax1.axvline(x=53, color="#f59e0b", linestyle=":", linewidth=1, alpha=0.7, label="53° (Starlink shell)")
ax1.axvline(x=97.5, color="#10b981", linestyle=":", linewidth=1, alpha=0.7, label="~97.5° (SSO)")
ax1.set_xlabel("Inclination (degrees)", fontsize=11, color=PRIMARY)
ax1.set_ylabel("Satellite Count", fontsize=11, color=PRIMARY)
ax1.set_title("Inclination Distribution (All Active Satellites)", fontsize=12,
              fontweight="bold", color=PRIMARY)
ax1.legend(fontsize=8, loc="upper left")
ax1.grid(axis="y", alpha=0.3)

# Zoomed: 0–100°
ax2.hist(incl, bins=100, range=(0, 100), color="#3b82f6", alpha=0.8, edgecolor="white", linewidth=0.3)
ax2.axvline(x=incl.median(), color="#ef4444", linestyle="--", linewidth=1.5,
            label=f"Median: {incl.median():.1f}°")
ax2.axvline(x=53, color="#f59e0b", linestyle=":", linewidth=1, alpha=0.7)
ax2.axvline(x=97.5, color="#10b981", linestyle=":", linewidth=1, alpha=0.7)
ax2.set_xlabel("Inclination (degrees)", fontsize=11, color=PRIMARY)
ax2.set_ylabel("Satellite Count", fontsize=11, color=PRIMARY)
ax2.set_title("Inclination Detail (0°–100°)", fontsize=12, fontweight="bold", color=PRIMARY)
ax2.legend(fontsize=8, loc="upper left")
ax2.grid(axis="y", alpha=0.3)

plt.tight_layout()
inclination_b64 = fig_to_b64(fig)

# ── Chart 6: Eccentricity Distribution ───────────────────────────────
print("Generating chart: eccentricity distribution...")
ecc = df["ECCENTRICITY"].dropna()
fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 5))

# Full range histogram
ax1.hist(ecc, bins=100, color="#8b5cf6", alpha=0.8, edgecolor="white", linewidth=0.3)
ax1.axvline(x=ecc.median(), color="#ef4444", linestyle="--", linewidth=1.5,
            label=f"Median: {ecc.median():.4f}")
ax1.axvline(x=0.25, color="#f59e0b", linestyle=":", linewidth=1, alpha=0.7,
            label="0.25 (HEO threshold)")
ax1.set_xlabel("Eccentricity", fontsize=11, color=PRIMARY)
ax1.set_ylabel("Satellite Count", fontsize=11, color=PRIMARY)
ax1.set_title("Eccentricity Distribution (Log Scale)", fontsize=12,
              fontweight="bold", color=PRIMARY)
ax1.set_yscale("log")
ax1.legend(fontsize=8)
ax1.grid(axis="y", alpha=0.3)

# Near-circular focus (0 - 0.02)
near_circ = ecc[ecc <= 0.02]
ax2.hist(near_circ, bins=80, color="#a78bfa", alpha=0.8, edgecolor="white", linewidth=0.3)
ax2.axvline(x=near_circ.median(), color="#ef4444", linestyle="--", linewidth=1.5,
            label=f"Median (near-circular): {near_circ.median():.5f}")
ax2.set_xlabel("Eccentricity", fontsize=11, color=PRIMARY)
ax2.set_ylabel("Satellite Count", fontsize=11, color=PRIMARY)
ax2.set_title("Near-Circular Orbits (ecc ≤ 0.02)", fontsize=12,
              fontweight="bold", color=PRIMARY)
ax2.legend(fontsize=8)
ax2.grid(axis="y", alpha=0.3)

plt.tight_layout()
eccentricity_b64 = fig_to_b64(fig)

# ── Chart 7: Mean Motion by Regime ───────────────────────────────────
print("Generating chart: mean motion by regime...")
regime_order = ["LEO", "MEO", "GEO", "HEO"]
regime_data = [df[df["ORBIT_REGIME"] == r]["MEAN_MOTION"].dropna() for r in regime_order]

fig, ax = plt.subplots(figsize=(10, 5))
bp = ax.boxplot(regime_data, labels=regime_order, patch_artist=True, showfliers=False)
for patch, regime in zip(bp["boxes"], regime_order):
    patch.set_facecolor(ORBIT_COLORS[regime])
    patch.set_alpha(0.7)

# Add count labels
for i, (r, d) in enumerate(zip(regime_order, regime_data)):
    ax.annotate(f"n={len(d):,}", xy=(i+1, d.median()),
                xytext=(i+1, ax.get_ylim()[1]*0.9 if i==0 else d.median()+1),
                fontsize=8, ha="center", color=PRIMARY)

ax.axhline(y=14, color="#2563eb", linestyle="--", alpha=0.4, linewidth=1)
ax.annotate("LEO threshold (>14)", xy=(0.6, 14), fontsize=8, color="#2563eb", alpha=0.7)
ax.axhline(y=1.0, color="#10b981", linestyle="--", alpha=0.4, linewidth=1)
ax.annotate("GEO (~1.0)", xy=(0.6, 1.0), fontsize=8, color="#10b981", alpha=0.7)
ax.set_ylabel("Mean Motion (revolutions/day)", fontsize=11, color=PRIMARY)
ax.set_title("Mean Motion Distribution by Orbital Regime", fontsize=13,
             fontweight="bold", color=PRIMARY)
ax.grid(axis="y", alpha=0.3)

plt.tight_layout()
mean_motion_b64 = fig_to_b64(fig)

# ── Chart 8: Launch Year Heatmap (decade x regime) ───────────────────
print("Generating chart: launch decade heatmap...")
valid = df.dropna(subset=["LAUNCH_YEAR_NUM", "ORBIT_REGIME"])
valid["DECADE"] = (valid["LAUNCH_YEAR_NUM"] // 10 * 10).astype(int)
decades = sorted(valid["DECADE"].unique())
regimes = ["LEO", "MEO", "GEO", "HEO"]

heatmap_data = pd.crosstab(valid["DECADE"], valid["ORBIT_REGIME"])[regimes]

fig, ax = plt.subplots(figsize=(10, 5))
im = ax.imshow(heatmap_data.T.values, cmap="Blues", aspect="auto")
ax.set_xticks(range(len(heatmap_data.index)))
ax.set_xticklabels(heatmap_data.index, rotation=45, ha="right", fontsize=9)
ax.set_yticks(range(len(regimes)))
ax.set_yticklabels(regimes, fontsize=9)
for i in range(len(regimes)):
    for j in range(len(heatmap_data.index)):
        val = heatmap_data.values[j, i]
        color = "white" if val > heatmap_data.values.max() * 0.6 else PRIMARY
        ax.text(j, i, f"{val:,}", ha="center", va="center", fontsize=8, color=color)
ax.set_title("Active Satellites by Launch Decade × Orbital Regime", fontsize=13,
             fontweight="bold", color=PRIMARY)
cbar = plt.colorbar(im, ax=ax, shrink=0.8)
cbar.set_label("Satellite Count", fontsize=9)
plt.tight_layout()
heatmap_b64 = fig_to_b64(fig)

# ── Additional stats ─────────────────────────────────────────────────
print("Computing supplementary statistics...")

# LEO share excluding Starlink
leo_non_starlink = ((df["ORBIT_REGIME"] == "LEO") & (df["CONSTELLATION"] != "Starlink")).sum()
leo_pct_no_sl = leo_non_starlink / total_sats * 100

# Constellation count
n_constellations = df["CONSTELLATION"].nunique()

# Regime breakdown table
regime_df = pd.DataFrame({
    "Regime": regime_order,
    "Count": [len(regime_data[0]), len(regime_data[1]), len(regime_data[2]), len(regime_data[3])],
    "Share (%)": [
        f"{len(regime_data[0])/total_sats*100:.1f}%",
        f"{len(regime_data[1])/total_sats*100:.1f}%",
        f"{len(regime_data[2])/total_sats*100:.1f}%",
        f"{len(regime_data[3])/total_sats*100:.1f}%",
    ],
    "Median Mean Motion": [
        f"{regime_data[0].median():.2f}",
        f"{regime_data[1].median():.2f}",
        f"{regime_data[2].median():.2f}",
        f"{regime_data[3].median():.2f}",
    ],
    "Median Inclination": [
        f"{df[df['ORBIT_REGIME']=='LEO']['INCLINATION'].median():.1f}°",
        f"{df[df['ORBIT_REGIME']=='MEO']['INCLINATION'].median():.1f}°",
        f"{df[df['ORBIT_REGIME']=='GEO']['INCLINATION'].median():.1f}°",
        f"{df[df['ORBIT_REGIME']=='HEO']['INCLINATION'].median():.1f}°",
    ],
})

# Eccentricity stats
ecc_mean = df["ECCENTRICITY"].mean()
ecc_median = df["ECCENTRICITY"].median()
ecc_max = df["ECCENTRICITY"].max()
high_ecc = (df["ECCENTRICITY"] > 0.25).sum()

# Inclination bands
polar_count = ((incl >= 85) & (incl <= 95)).sum()
equatorial_count = (incl < 10).sum()
sso_count = ((incl >= 97) & (incl <= 99)).sum()

# ── Build HTML Report ────────────────────────────────────────────────
print("Building HTML report...")

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Active Satellites in Earth Orbit — 2026 Catalog Analysis</title>
<style>
:root {{
  --primary: #1b2a4a;
  --accent: #2563eb;
  --accent-light: #dbeafe;
  --bg: #f8fafc;
  --card-bg: #ffffff;
