  --success: #10b981;
  --warning: #f59e0b;
  --danger: #ef4444;
}}
* {{ margin: 0; padding: 0; box-sizing: border-box; }}
body {{
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
}}
.container {{ max-width: 1100px; margin: 0 auto; padding: 20px 24px; }}

/* Header */
.report-header {{
  background: linear-gradient(135deg, var(--primary) 0%, #1e3a5f 100%);
  color: white;
  padding: 48px 0 36px;
  text-align: center;
}}
.report-header h1 {{ font-size: 2rem; font-weight: 700; letter-spacing: -0.01em; }}
.report-header .subtitle {{
  font-size: 1rem; color: #94a3b8; margin-top: 6px;
}}
.report-header .meta {{ font-size: 0.8rem; color: #64748b; margin-top: 12px; }}

/* KPI Cards */
.kpi-grid {{
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  margin: -30px 0 32px;
  position: relative;
  z-index: 2;
}}
.kpi-card {{
  background: var(--card-bg);
  border-radius: 10px;
  padding: 20px 16px;
  text-align: center;
  box-shadow: 0 2px 12px rgba(0,0,0,0.06);
  border-top: 3px solid var(--accent);
}}
.kpi-card .kpi-value {{ font-size: 1.6rem; font-weight: 700; color: var(--primary); }}
.kpi-card .kpi-label {{ font-size: 0.75rem; color: var(--text-secondary); margin-top: 4px; line-height: 1.3; }}

/* Sections */
section {{ margin: 32px 0; }}
.section-title {{
  font-size: 1.4rem; font-weight: 700; color: var(--primary);
  border-bottom: 2px solid var(--accent-light); padding-bottom: 8px; margin-bottom: 20px;
}}
.section-title .num {{ color: var(--accent); font-size: 0.9rem; margin-right: 6px; }}

/* Text */
p {{ margin-bottom: 14px; color: var(--text); font-size: 0.95rem; }}
.narrative {{
  background: var(--card-bg);
  border-left: 4px solid var(--accent);
  padding: 16px 20px;
  margin-bottom: 20px;
  border-radius: 0 8px 8px 0;
  font-size: 0.95rem;
}}

/* Charts */
.chart-container {{
  background: var(--card-bg);
  border-radius: 10px;
  padding: 20px;
  margin: 20px 0;
  box-shadow: 0 1px 4px rgba(0,0,0,0.04);
  text-align: center;
}}
.chart-container img {{ max-width: 100%; height: auto; }}

/* Callout */
.callout {{
  padding: 16px 20px; border-radius: 8px; margin: 16px 0; font-size: 0.9rem;
}}
.callout-info {{ background: #dbeafe; border: 1px solid #93c5fd; }}
.callout-warning {{ background: #fef3c7; border: 1px solid #fcd34d; }}
.callout-success {{ background: #d1fae5; border: 1px solid #6ee7b7; }}

/* Tables */
.data-table {{
  width: 100%; border-collapse: collapse; margin: 16px 0;
  font-size: 0.9rem; background: var(--card-bg); border-radius: 8px; overflow: hidden;
  box-shadow: 0 1px 4px rgba(0,0,0,0.04);
}}
.data-table th {{
  background: var(--primary); color: white; padding: 10px 14px; text-align: left;
  font-weight: 600; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.03em;
}}
.data-table td {{ padding: 10px 14px; border-bottom: 1px solid var(--border); }}
.data-table tr:last-child td {{ border-bottom: none; }}
.data-table tr:nth-child(even) {{ background: #f8fafc; }}
.data-table .highlight {{ font-weight: 700; color: var(--accent); }}

/* Two-column */
.two-col {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin: 20px 0; }}
@media (max-width: 768px) {{ .two-col {{ grid-template-columns: 1fr; }} .kpi-grid {{ grid-template-columns: repeat(3, 1fr); }} }}

/* Footer */
footer {{
  text-align: center; padding: 32px 24px;
  color: var(--text-secondary); font-size: 0.8rem; border-top: 1px solid var(--border); margin-top: 40px;
}}
</style>
</head>
